import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>GIF — это короткая зацикленная анимация, сделанная из серии неподвижных изображений. Она играет без звука, повторяется бесконечно или заданное число раз и работает почти в каждом чате, ленте соцсетей и на сайте. Хорошо сделанный GIF за две секунды говорит то, что не скажет абзац.</p>\n<p><a href=\"/ru/sozdat-gif/\">Создатель GIF</a> превращает ваши фото в анимированный GIF в браузере. Загрузите два или более изображений-кадров, задайте время для каждого кадра, выберите число повторов и скачайте GIF89a без водяного знака. Ничего не загружается на сервер.</p>\n<p>Это руководство объясняет, как работают GIF, как выбирать кадры и время их показа и как держать размер файла достаточно малым для обмена. Делаете ли вы GIF-реакцию, демонстрацию товара или обучающий ролик, принципы одни и те же.</p>\n<h2 id=\"what-is-a-gif\">Что такое GIF</h2>\n<p>GIF означает Graphics Interchange Format, и существует он с конца 1980-х годов. Это один из старейших форматов изображений, до сих пор используемых каждый день, а его живучесть объясняется одной функцией: анимацией без видео.</p>\n<p>GIF хранит серию кадров, каждый из которых показывается короткое время, один за другим. Проигрыватель проходит по кадрам по кругу, и результат выглядит как короткий видеоклип. Нет ни звука, ни элементов управления проигрывателем, ни нужды в видеокодеке.</p>\n<p>GIF ограничены 256 цветами на кадр, поэтому они лучше подходят иллюстрациям, скриншотам и простым анимациям, чем полноцветным фотографиям. Фото-GIF работает, но ограниченная палитра может сделать градиенты полосатыми, а тона кожи — плоскими.</p>\n<p>Формат универсален. Чаты, ленты соцсетей, форумы, почта и сайты показывают GIF без специального проигрывателя. Именно эта универсальность делает GIF до сих пор самым лёгким способом поделиться короткой анимацией с кем угодно.</p>\n<h2 id=\"how-the-gif-maker-works\">Как работает создатель GIF</h2>\n<p>Создатель GIF кодирует ваши фото в анимированный GIF полностью в вашем браузере. Ваши кадры никогда не покидают устройство, что важно, когда изображения — это неопубликованные снимки товара или личные фото. Нет ни загрузки, ни очереди, ни ожидания сервера.</p>\n<p>Вы загружаете два или более изображений-кадров, и инструмент располагает их по порядку. Кадры можно менять местами перетаскиванием, дублировать кадр, чтобы удержать его дольше, и удалять кадр, который не принадлежит анимации. Список кадров — это шкала времени вашей анимации.</p>\n<p>Каждый кадр получает свою задержку, измеряемую в долях секунды. Короткая задержка делает анимацию быстрой, а длинная — медленной. Можно также задать одну задержку для всех кадров, а затем поправить отдельные кадры, которым нужно задержаться.</p>\n<p>Предпросмотр живого времени показывает анимацию, играющую с вашими текущими настройками, до того, как вы создадите файл. То, что вы видите в предпросмотре, — это то, как будет выглядеть готовый GIF, поэтому проверьте его перед скачиванием. Созданный файл — стандартный GIF89a, который играет везде, где поддерживаются GIF.</p>\n<h2 id=\"choosing-frames\">Как выбирать кадры</h2>\n<p>Кадры — это неподвижные изображения, из которых состоит анимация, и выбор кадров решает, сработает ли GIF. Хороший GIF рассказывает маленькую историю: «до» и «после», поворот товара, пошаговое действие или реакцию, которая нарастает и разрешается.</p>\n<p>Используйте кадры, похожие по размеру и форме. Инструмент справляется с изображениями разного соотношения сторон, но набор кадров с совпадающими размерами даёт плавную анимацию без прыжков и чёрных полос. Сначала измените размер или обрежьте кадры, если они сильно различаются.</p>\n<p>Держите число кадров умеренным. GIF с пятью-пятнадцатью кадрами обычно достаточно для реакции, демонстрации или короткого шага обучения. Больше кадров означает более длинную анимацию и больший файл, а очень длинный GIF теряет ударность, которая делает формат рабочим.</p>\n<p>Порядок важнее числа. Поворот товара читается по часовой стрелке или против, обучение — в порядке шагов, а реакция — как нарастание и развязка. Расположите кадры так, чтобы движение казалось естественным, затем проверьте предпросмотр.</p>\n<h2 id=\"frame-delays-and-timing\">Задержки кадров и время показа</h2>\n<p>Задержка кадра — это то, как долго каждый кадр остаётся на экране, и это главный регулятор ощущения анимации. Задержка 0,1 секунды на кадр даёт быстрое, энергичное движение, а задержка 0,5 секунды — медленное, обдуманное.</p>\n<p>Используйте единую задержку для основной части анимации и более длинную — для кадров, которым нужно внимание. Титульный слайд в начале заслуживает более долгой выдержки, чтобы зрители могли его прочитать, а финальный кадр — более долгой, чтобы сообщение закрепилось до перезапуска цикла.</p>\n<p>Быстрые предустановки 1, 2, 5 и 10 кадров в секунду дают отправные точки. Один кадр в секунду — медленное слайд-шоу, пять кадров в секунду — бодрая демонстрация, а десять кадров в секунду — достаточно плавно для простого движения. Начните с предустановки, затем точно настройте отдельные кадры.</p>\n<p>Проверьте время в предпросмотре живого времени. Задержка, которая как число выглядит правильно, в движении может ощущаться неправильно, а предпросмотр показывает настоящее ощущение. Если анимация проносится мимо важного кадра, удлините этот кадр, а не замедляйте весь GIF.</p>\n<h2 id=\"frame-rate-presets\">Предустановки частоты кадров</h2>\n<p>Предустановки переводят кадры в секунду в задержки. Один кадр в секунду означает, что каждый кадр показывается одну секунду, что подходит слайд-шоу из неподвижных изображений, где каждое заслуживает полного взгляда. Два кадра в секунду означают полсекунды на кадр, что подходит медленной демонстрации.</p>\n<p>Пять кадров в секунду означают пятую часть секунды на кадр — золотая середина для большинства GIF. Это достаточно быстро, чтобы ощущаться как движение, и достаточно медленно, чтобы каждый кадр регистрировался. Демонстрации товаров, обучение и простые анимации обычно живут при этой скорости.</p>\n<p>Десять кадров в секунду означают десятую часть секунды на кадр — самая плавная скорость, которую предлагает инструмент. Она подходит движению, которое должно выглядеть текучим, например вращению или циклу ходьбы, но это также означает больше кадров на секунду анимации и больший файл.</p>\n<p>Больше — не всегда лучше. GIF при десяти кадрах в секунду с тридцатью кадрами длится три секунды и тяжёлый, а та же идея при пяти кадрах в секунду с пятнадцатью кадрами длится три секунды и вдвое меньше. Подбирайте скорость под движение, а не под максимум.</p>\n<h2 id=\"loop-options\">Варианты зацикливания</h2>\n<p>Зацикливание решает, сколько раз играет GIF. Бесконечный цикл играет вечно — это классическое поведение GIF и правильный выбор для реакций, украшений и всего, что должно снова и снова привлекать взгляд.</p>\n<p>Конечный цикл играет заданное число раз, а затем останавливается на финальном кадре. Это подходит обучению или демонстрации, где зритель должен закончить на готовом состоянии, а не на кадре посреди анимации. Число повторов два или три даёт второй взгляд, не зацикливаясь вечно.</p>\n<p>Одиночное воспроизведение, или число повторов один, показывает анимацию один раз и останавливается. Это подходит сообщению, где анимация — разовое раскрытие, например «до и после», которое должно закончиться на «после». Зритель видит изменение, затем результат остаётся.</p>\n<p>Выбирайте цикл под контекст. Реакция в чате хочет бесконечный цикл, демонстрация товара — несколько повторов, а шаг обучения — остановку на результате. Неправильный цикл заставляет хороший GIF казаться сломанным.</p>\n<h2 id=\"frame-fit-contain-vs-cover\">Вписывание кадра: «вместить» или «заполнить»</h2>\n<p>Вписывание кадра решает, что происходит, когда кадры имеют разные соотношения сторон. «Вместить» вписывает каждый кадр в выходной размер без обрезки, поэтому весь кадр виден, а пустое место становится границей. Это сохраняет полное изображение ценой пустых полос.</p>\n<p>«Заполнить» заполняет выходной размер полностью, обрезая кадр, поэтому пустых полос нет, но края кадра могут быть отрезаны. Это даёт чистую анимацию на всю площадь ценой потери краёв некоторых кадров.</p>\n<p>Выбирайте «Вместить», когда важна каждая часть каждого кадра, например в обучении, где обрезанная кнопка скрыла бы шаг. Выбирайте «Заполнить», когда анимация должна чисто заполнить кадр, например в посте соцсети, где пустые полосы выглядели бы недоделанными.</p>\n<p>Соотношение сторон остаётся фиксированным, когда вы редактируете выходную ширину, поэтому изменение ширины масштабирует весь GIF, а не растягивает его. Задайте выходные размеры один раз, выберите вписывание — и кадры следуют согласованно.</p>\n<h2 id=\"output-size-and-dimensions\">Выходной размер и габариты</h2>\n<p>Выходная ширина задаёт ширину готового GIF в пикселях, а высота следует из соотношения сторон кадров. Ширина 480 пикселей — распространённый выбор для чатов и обмена в соцсетях, а большая ширина подходит сайту или презентации.</p>\n<p>Меньше обычно лучше для GIF. GIF шириной 480 пикселей достаточно мал, чтобы быстро поделиться, и достаточно велик, чтобы чётко видеть на телефоне. GIF шириной 1000 пикселей — это в четыре раза больше пикселей и в несколько раз больше размер файла при разнице, которую большинство зрителей не заметит.</p>\n<p>Инструмент задаёт минимум и максимум выходных размеров, поэтому экстремальные размеры невозможны. Очень маленькие выходные данные теряют детали, а очень большие создают файлы, слишком большие для обмена. Держитесь середины диапазона для лучшего баланса.</p>\n<p>Проверяйте размеры по месту назначения. Чат-приложение может всё равно уменьшить большой GIF, поэтому отправка огромного файла тратит трафик без видимой выгоды. Баннеру сайта нужна большая ширина, чем стикеру в чате, поэтому подбирайте размер под место.</p>\n<h2 id=\"color-palette-quality\">Качество цветовой палитры</h2>\n<p>GIF хранят не более 256 цветов на кадр, поэтому кодер должен выбрать, какие цвета сохранить. Ползунок «Качество цветовой палитры» управляет тем, насколько тщательно делается этот выбор. Более высокое значение анализирует кадры тщательнее и сохраняет цвета, которые важнее всего.</p>\n<p>Более высокое качество даёт более плавные градиенты и более точные тона кожи, но кодирование занимает больше времени и может дать чуть больший файл. Более низкое качество кодируется быстрее и даёт меньшие файлы, но градиенты могут полосить, а тонкие цвета — смещаться.</p>\n<p>Для фотографий используйте более высокое качество палитры. У фото тысячи цветов, и тщательная палитра сохраняет изображение узнаваемым. Для иллюстраций и скриншотов с малым числом цветов достаточно низкой настройки, потому что палитра всё равно может вместить все цвета.</p>\n<p>Проверьте палитру на кадре с градиентом или лицом. Именно там плохая палитра показывается первой: полосатостью в небе или пятнами на коже. Если тестовый кадр выглядит чисто, остальной GIF тоже будет чистым.</p>\n<h2 id=\"large-gif-warning\">Предупреждение о большом GIF</h2>\n<p>Инструмент показывает предупреждение о большом GIF, когда оценочный файл превышает 5 МБ или 15 МБ. Эти пороги существуют, потому что большие GIF трудно передавать: они медленно загружаются в чатах, могут отклоняться лимитами загрузки и съедают мобильный трафик.</p>\n<p>GIF становится большим по трём причинам: много кадров, большие размеры или высокая частота кадров. Сокращение любого из трёх уменьшает файл. Меньше кадров — обычно лучший срез, потому что более короткий GIF — это также лучший GIF.</p>\n<p>Когда появляется предупреждение, сначала уменьшите выходную ширину. Уменьшение ширины вдвое сокращает число пикселей до четверти — это самая большая единичная экономия. Затем уменьшите число кадров или частоту кадров, пока предупреждение не исчезнет.</p>\n<p>Если GIF должен остаться большим, подумайте, правильный ли это формат. Короткое видео в формате MP4 намного меньше той же анимации в виде GIF, и большинство платформ принимают видео. <a href=\"/ru/szhat-gif/\">Сжиматель GIF</a> может уменьшить готовый GIF, но видео — лучший выбор, когда размер — главная проблема.</p>\n<h2 id=\"transparency-in-gifs\">Прозрачность в GIF</h2>\n<p>GIF поддерживают прозрачность, но только как один прозрачный цвет, а не как плавный альфа-канал. Пиксель либо полностью прозрачен, либо полностью непрозрачен, поэтому мягкие края и тени становятся жёсткими на прозрачном фоне.</p>\n<p>Создатель GIF сохраняет прозрачные фоны из PNG-кадров, когда выход настроен для этого. Логотип или стикер с прозрачностью сохраняет свои прозрачные области, что подходит наложениям и стикерам в чате, которые должны сидеть на любом фоне.</p>\n<p>Мягкие края требуют осторожности. Логотип с тенью или растушёванным краем покажет ореол, когда прозрачность сведётся к одному цвету, потому что полупрозрачные пиксели должны стать либо сплошными, либо прозрачными. Графика с жёсткими краями работает лучше мягкой.</p>\n<p>Проверьте прозрачный GIF и на светлом, и на тёмном фоне. Ореол, невидимый на белом, может быть очевиден на чёрном, и наоборот. Если ореол виден, вместо прозрачности наложите графику на сплошной цвет.</p>\n<h2 id=\"common-mistakes\">Частые ошибки</h2>\n<p>Самая частая ошибка — слишком много кадров. GIF с пятьюдесятью кадрами — это видео под маской, и он будет тяжёлым, медленным и скучным. Сократите список кадров до существенных моментов — и GIF станет резче и меньше одновременно.</p>\n<p>Другая ошибка — единая задержка для каждого кадра. Титульный слайд, показанный десятую часть секунды, прочитать нельзя, а финальный кадр, показанный десятую часть секунды, не закрепится. Дайте важным кадрам более длинные задержки, а кадрам движения — более короткие.</p>\n<p>Третья ошибка — огромный выходной размер. GIF, экспортированный при ширине 1000 пикселей для сообщения в чате, — это в четыре раза больше пикселей, чем версия 500 пикселей, а чат-приложение всё равно уменьшит его. Подбирайте размер под место назначения.</p>\n<p>Наконец, многие игнорируют качество палитры на фото-GIF. Низкая настройка палитры превращает фото в постеризованный беспорядок с полосатым небом и пятнистой кожей. Поднимите качество палитры для фотографий и держите его низким только для простой графики.</p>\n<p>GIF отлично работают и в рабочих чатах. Короткая анимация «как это сделать» в Slack или корпоративном мессенджере объясняет шаг быстрее, чем длинное текстовое сообщение, и её можно пересмотреть, не открывая видео.</p>\n<p>Для поздравлений в WhatsApp и Telegram GIF — почти стандарт. Короткая анимация с тортом или салютом передаёт настроение лучше статичной открытки, а сделать её можно из двух-трёх своих фото за пару минут.</p>\n<p>Если вы делаете GIF для сайта, следите за весом страницы. Один GIF на 3 МБ замедляет загрузку, а три таких GIF на одной странице заметят даже посетители с быстрым интернетом. Для сайта держите GIF маленькими.</p>\n<p>Сохраняйте кадры в отдельной папке с понятными именами. Через месяц вы захотите сделать вторую версию GIF, и кадры позволят собрать её за минуты, а не искать исходники по всему компьютеру.</p>\n<p>И помните главное правило GIF: короче — лучше. Анимация, которая доносит мысль за две секунды, запомнится, а анимация на десять секунд, которую никто не досматривает, — нет.</p>\n<h2 id=\"quick-reference\">Краткая справка: чек-лист создателя GIF</h2>\n<p>Выберите от пяти до пятнадцати кадров с совпадающими размерами, расположите их в порядке истории и задайте базовую задержку около пяти кадров в секунду. Дайте титульному и финальному кадрам более долгие выдержки и выберите число повторов под контекст.</p>\n<p>Задайте выходную ширину под место назначения, используйте «Вместить», когда важна каждая деталь, и «Заполнить», когда кадр должен заполняться чисто, а для фотографий поднимите качество палитры. Прислушайтесь к предупреждению о большом GIF и сначала уменьшите ширину.</p>\n<p>Пошаговую сборку читайте в статье <a href=\"/ru/blog/kak-sdelat-gif-iz-foto/\">Как сделать GIF из фото</a>, а компромисс размера подробно — в статье <a href=\"/ru/blog/gif-chastota-kadrov-i-razmer-fajla/\">GIF: частота кадров и размер файла — плавность или компактность</a>. Сделайте свой GIF в <a href=\"/ru/sozdat-gif/\">создателе GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Что такое GIF и чем он отличается от видео?","answer":"GIF — это серия неподвижных изображений, которые играют по кругу, без звука и без элементов управления проигрывателем. Видео использует кодек, чтобы сжать движение и звук в намного меньший файл. GIF больше, но играют везде без проигрывателя, поэтому они доминируют в чатах и лентах соцсетей."},{"question":"Сколько кадров должно быть в GIF?","answer":"От пяти до пятнадцати кадров достаточно для большинства GIF: реакции, демонстрации товара или короткого шага обучения. Больше кадров означает более длинную анимацию и больший файл. Если вашему GIF нужно пятьдесят кадров, это, вероятно, видео, и формат видео послужит ему лучше."},{"question":"Почему файлы GIF такие большие?","answer":"GIF хранят каждый кадр как полное изображение с палитрой 256 цветов и плохо сжимаются по сравнению с видео. Много кадров, большие размеры и высокая частота кадров увеличивают размер. Сначала уменьшите ширину, затем число кадров, чтобы быстро уменьшить GIF."},{"question":"Можно ли сделать GIF из видео?","answer":"Создатель GIF строит GIF из неподвижных изображений, а не из видеофайлов. Чтобы превратить видео в GIF, сначала извлеките из видео серию неподвижных кадров, затем загрузите эти кадры как кадры GIF. Выберите кадры, которые несут нужное движение."},{"question":"Работают ли GIF на всех платформах соцсетей?","answer":"Почти на всех. Чаты, ленты соцсетей, форумы и почта показывают GIF без специального проигрывателя. Несколько платформ автоматически преобразуют загруженные GIF в видео, но анимация всё равно играет, поэтому для зрителя результат тот же."},{"question":"Какой размер лучше всего подходит для GIF?","answer":"Около 480 пикселей в ширину — хороший вариант по умолчанию для чатов и обмена в соцсетях: достаточно мал, чтобы быстро отправить, и достаточно велик, чтобы чётко видеть на телефоне. Используйте большую ширину только для сайта или презентации, где GIF показывается крупнее."}];
